/// What a session's status dot says.
public enum BriareusStatusRole: String, Sendable, CaseIterable {
    /// Working, or about to.
    case active
    /// Done with its turn and ready for the next message.
    case idle
    /// Stopped short: waiting on you, interrupted or cancelled.
    case attention
    case failed
    /// Closed, or a status this version does not know.
    case inactive

    /// The role of a server status string; one this version does not know is `inactive`.
    public init(status: String?) {
        switch status {
        case "running", "queued", "preparing", "starting": self = .active
        case "idle": self = .idle
        case "waiting", "interrupted", "cancelled": self = .attention
        case "failed", "error": self = .failed
        case "closed": self = .inactive
        default: self = .inactive
        }
    }
}

